<script setup lang="ts">import {Link,router} from '@inertiajs/vue3';import AdminLayout from '@/Layouts/AdminLayout.vue';import PageMeta from '@/Components/PageMeta.vue';import EmptyState from '@/Components/EmptyState.vue';import Pagination from '@/Components/Pagination.vue';import type {Paginated,Specialty} from '@/types';defineProps<{specialties:Paginated<Specialty>}>();const activate=(item:Specialty)=>router.patch(route('admin.specialties.activation',item.id),{active:!item.is_active},{preserveScroll:true});</script>
<template><AdminLayout title="Especialidades" eyebrow="Catálogos"><PageMeta title="Catálogo de especialidades" noindex/><section class="admin-content"><div class="content-toolbar"><div><p class="kicker">Catálogo público</p><h2>{{ specialties.total }} especialidades</h2></div><Link class="button button--admin" :href="route('admin.specialties.create')">+ Nueva especialidad</Link></div><div class="panel table-panel"><div v-if="specialties.data.length" class="table-scroll"><table><thead><tr><th>Nombre</th><th>Slug</th><th>Publicación</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in specialties.data" :key="item.id"><td><strong>{{ item.name }}</strong><small>{{ item.short_description||item.description||'Sin descripción confirmada' }}</small></td><td><code>{{ item.slug }}</code></td><td>{{ item.is_public?'Pública':'No pública' }}</td><td><span :class="['catalog-state',item.is_active?'on':'off']">{{ item.is_active?'Activa':'Inactiva' }}</span></td><td><div class="row-actions"><Link class="row-action" :href="route('admin.specialties.edit',item.id)">Editar</Link><button class="row-action" type="button" @click="activate(item)">{{ item.is_active?'Desactivar':'Activar' }}</button></div></td></tr></tbody></table></div><EmptyState v-else title="No hay especialidades configuradas"/><Pagination :links="specialties.links"/></div></section></AdminLayout></template>
